import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} PrimitiveConfig
 * @property {string} name
 * @property {Object} params
 *
 * @typedef {Object} InteractionConfig
 * @property {string} event   // e.g., "hover", "click"
 * @property {string} effect  // e.g., "preset:rise-in (subtle, 0.15 scene units)", "emit:hub-journal.select"
 *
 * @typedef {Object} NodeConfig
 * @property {string} meshUrl
 * @property {[number,number,number]} position
 * @property {[number,number,number]} rotation
 * @property {[number,number,number]} scale
 * @property {Object.<string,string>} colors   // {ink,paper,accent,surface}
 * @property {PrimitiveConfig[]} cinematicPrimitives
 * @property {InteractionConfig[]} interactions
 */

/**
 * @typedef {Object} NodeContext
 * @property {{load: (url:string)=>any}} glbLoader
 * @property {{[key:string]:(obj:THREE.Object3D,params:any)=>void}} primitives
 * @property {{emit?: (event:string)=>void}} [emit]            // optional event emitter helper
 */

/**
 * Creates the journal badge node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// container
	const root = new THREE.Object3D();

	// ---- Load GLB -------------------------------------------------
	const glb = ctx.glbLoader.load(config.meshUrl);
	if (!glb) {
		console.warn('GLB not loaded:', config.meshUrl);
		return root;
	}
	const meshRoot = glb.scene || glb;
	root.add(meshRoot);

	// ---- Apply transform -------------------------------------------
	const [px, py, pz] = config.position || [0, 0, 0];
	const [rx, ry, rz] = config.rotation || [0, 0, 0];
	const [sx, sy, sz] = config.scale || [1, 1, 1];
	root.position.set(px, py, pz);
	root.rotation.set(rx, ry, rz);
	root.scale.set(sx, sy, sz);

	// ---- Apply design token material tweaks -------------------------
	const accentColor = new THREE.Color(config.colors?.accent || '#ff2a38');
	meshRoot.traverse((obj) => {
		if (obj.isMesh && obj.material) {
			const mat = obj.material;
			// Ensure we work with an array for multi‑material meshes
			const materials = Array.isArray(mat) ? mat : [mat];
			materials.forEach((m) => {
				// Machined‑metal adjustments (within allowed limits)
				m.metalness = Math.min(m.metalness ?? 0, 0.55);
				m.roughness = Math.max(m.roughness ?? 0.5, 0.5);
				m.clearcoat = Math.min(m.clearcoat ?? 0, 0.25);
				m.clearcoatRoughness = Math.max(m.clearcoatRoughness ?? 0, 0.5);
				// Accent rim‑light – emissive layer
				m.emissive = accentColor;
				m.emissiveIntensity = 0.4;
			});
		}
	});

	// ---- Apply cinematic primitives ---------------------------------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const primitiveFn = ctx.primitives[prim.name];
			if (typeof primitiveFn === 'function') {
				primitiveFn(root, prim.params ?? {});
			}
		}
	}

	// ---- Interaction handling ---------------------------------------
	const originalY = root.position.y;
	const hoverTimeline = gsap.timeline({ paused: true });
	hoverTimeline.to(root.position, {
		y: originalY + 0.15,
		duration: 0.7,
		ease: 'power3.out',
	});

	const handlers = {};

	for (const interaction of config.interactions || []) {
		if (interaction.event === 'hover') {
			handlers.hover = () => {
				hoverTimeline.play(0);
			};
			handlers.hoverout = () => {
				hoverTimeline.reverse(0);
			};
		}
		if (interaction.event === 'click' && interaction.effect?.startsWith('emit:')) {
			const eventName = interaction.effect.split(':')[1];
			handlers.click = () => {
				if (ctx.emit && typeof ctx.emit === 'function') {
					ctx.emit(eventName);
				}
			};
		}
	}

	// expose handlers via userData
	root.userData.handlers = handlers;

	// ---- Cleanup ----------------------------------------------------
	root.userData.cleanup = () => {
		// kill GSAP timelines
		hoverTimeline.kill();

		// dispose geometry, material, textures
		meshRoot.traverse((obj) => {
			if (obj.isMesh) {
				if (obj.geometry) obj.geometry.dispose();
				if (Array.isArray(obj.material)) {
					obj.material.forEach((m) => {
						disposeMaterial(m);
					});
				} else if (obj.material) {
					disposeMaterial(obj.material);
				}
			}
		});
	};

	/**
	 * Helper to dispose a material and its textures.
	 * @param {THREE.Material} material
	 */
	function disposeMaterial(material) {
		for (const key in material) {
			const value = material[key];
			if (value && value.isTexture) {
				value.dispose();
			}
		}
		material.dispose();
	}

	return root;
}
